function prjSum(id){let sp=0,n=0,last='';const cat={};for(const t of S.tx){if(t.prj!==id||t.type!=='exp')continue;sp+=t.amt;n++;cat[t.cat]=(cat[t.cat]||0)+t.amt;if(t.date>last)last=t.date}return{sp,n,cat,last}}

const accOf=id=>S.acc.find(a=>a.id===id)||{name:'Account',type:'bank'};
const catOf=id=>CATS.find(c=>c.id===id)||SRCS.find(c=>c.id===id)||{n:'Other',s:'Other',i:'dots',c:'#64748b'};
const cic=(id,sz=20)=>`<span class="ico cico" style="--c:${catOf(id).c}">${ic(catOf(id).i,sz)}</span>`;
function delta(t,a){const x=t.amt;switch(t.type){case'exp':case'lend':case'repayOut':return t.acc===a?-x:0;case'inc':case'borrow':case'repayIn':case'adj':return t.acc===a?x:0;case'tr':return(t.acc===a?-x:0)+(t.to===a?x:0)}return 0}
const bal=a=>a.open+S.tx.reduce((s,t)=>s+delta(t,a.id),0);
function people(){const m={};for(const t of S.tx){if(!t.person||!['lend','borrow','repayIn','repayOut'].includes(t.type))continue;const v={lend:1,repayIn:-1,borrow:-1,repayOut:1}[t.type]*t.amt;m[t.person]=(m[t.person]||0)+v}return m}
function stats(p,withPrj){const r={exp:0,inc:0,prj:0,loan:0,cat:{},acc:{},src:{},day:{}};for(const t of S.tx){if(!inP(t,p))continue;if(t.type==='exp'&&t.prj){r.prj+=t.amt;if(!withPrj)continue}else if(t.type==='exp'&&t.cat==='emi'){r.loan+=t.amt;if(!withPrj)continue}if(t.type==='exp'){r.exp+=t.amt;r.cat[t.cat]=(r.cat[t.cat]||0)+t.amt;r.acc[t.acc]=(r.acc[t.acc]||0)+t.amt;r.day[t.date]=(r.day[t.date]||0)+t.amt}else if(t.type==='inc'){r.inc+=t.amt;r.src[t.cat]=(r.src[t.cat]||0)+t.amt}}return r}
const LB=()=>addD(TODAY,-35),W30=()=>addD(TODAY,30);
const emiLeft=c=>c.total?Math.max(0,c.total-c.done):99;
const gSaved=c=>(c.start||0)+S.tx.filter(t=>t.cid===c.id&&t.type==='tr').reduce((s,t)=>s+t.amt,0);
function cocc(c){if(c.cleared)return[];if(c.goal){const from=c.since&&c.since>LB()?c.since:LB();return occ(c,from,c.date).filter(d=>!c.paid.includes(d)&&!c.skip.includes(d))}if(c.once)return c.paid.includes(c.date)||c.skip.includes(c.date)?[]:[c.date];const from=c.since||LB();return occ(c,from,addD(TODAY,400)).filter(d=>!c.paid.includes(d)&&!c.skip.includes(d))}
const nextDue=c=>emiLeft(c)>0?(cocc(c)[0]||null):null;
const dueOccs=c=>c.goal&&gSaved(c)>=c.amt?[]:cocc(c).filter(d=>d<=W30()).slice(0,c.goal?1:emiLeft(c));
function camt(c){if(!c.goal)return c.amt;const rem=Math.max(0,c.amt-gSaved(c)),n=Math.max(1,cocc(c).length);return Math.min(rem,Math.ceil(rem/n/100)*100)}
function goalMsg(c){const s=gSaved(c),p=Math.round(s/c.amt*100);return p>=100?`Goal reached! ${c.name}: ${fmt(s)} saved.`:p>=75?`Almost there. ${c.name}: ${fmt(s)} · ${p}%`:p>=50?`Halfway! ${c.name}: ${fmt(s)} · ${p}%`:`Nice. ${c.name}: ${fmt(s)} saved · ${p}% there`}
function guessCat(n){n=n.toLowerCase();return /loan|emi|kista|instal/.test(n)?'emi':/rent|bhada|flat|room/.test(n)?'rent':/electric|bijuli|water|khanepani|internet|wifi|phone|recharge|gas/.test(n)?'bills':/netflix|spotify|youtube|prime|subscri|streaming/.test(n)?'fun':/insur|bima/.test(n)?'health':/school|fee|tuition|college|course/.test(n)?'edu':'other'}
function dayInfo(free){const ni=S.inc.map(incNext).filter(Boolean).sort()[0];const end=ni||addD(period(0).b,-1);const days=Math.max(1,dd(TODAY,end));return{end,days,per:Math.floor(Math.max(0,free)/days),inc:!!ni}}
function cstat(c){if(c.cleared)return'done';if(c.goal&&gSaved(c)>=c.amt)return'done';if(c.total&&emiLeft(c)<=0)return'done';const d=nextDue(c);if(!d)return'paid';if(d<TODAY)return'overdue';if(d===TODAY)return'today';if(d<=W30())return'upcoming';return'later'}
const lastPaid=c=>c.paid.slice().sort().pop()||null;
const UNPAID=['overdue','today','upcoming'];
function reserved(id){return S.com.filter(c=>c.acc===id).reduce((s,c)=>s+camt(c)*dueOccs(c).length,0)}
function incOcc(r){const from=r.since>LB()?r.since:LB();return occ({due:r.day,cal:r.cal},from,TODAY).filter(d=>!r.got.includes(d)&&!(r.skip||[]).includes(d))}
const incPending=r=>r.snooze&&r.snooze>TODAY?null:(incOcc(r).pop()||null);
const incNext=r=>occ({due:r.day,cal:r.cal},addD(TODAY,1),addD(TODAY,400))[0]||null;
function shortOf(c){const x=shortList().find(s=>s.id===c.acc&&s.items.some(([k])=>k.id===c.id));return x?{gap:Math.ceil(x.need-x.bal),acc:x.id}:null}
function shortList(){const lim=addD(TODAY,5),m={};for(const c of S.com){const a=accOf(c.acc);if(a.type==='card'||a.archived)continue;const L=dueOccs(c).filter(d=>d<=lim);if(!L.length)continue;m[c.acc]=m[c.acc]||{need:0,items:[]};m[c.acc].need+=camt(c)*L.length;m[c.acc].items.push([c,L[0]])}return Object.entries(m).map(([id,v])=>({id,need:v.need,items:v.items,bal:bal(accOf(id))})).filter(x=>x.bal<x.need)}
function allTags(){const m=new Map();S.tx.slice().sort((x,y)=>y.date.localeCompare(x.date)).forEach(t=>{if(t.tag&&!m.has(t.tag))m.set(t.tag,1)});S.com.forEach(c=>{if(c.tag&&!m.has(c.tag))m.set(c.tag,1)});return[...m.keys()]}
const ORDER={overdue:0,today:1,upcoming:2,later:3,paid:4,skipped:5,done:6};
const PILL={overdue:'<span class="pill w">Overdue</span>',today:'<span class="pill dk">Due today</span>',upcoming:'<span class="pill">Upcoming</span>',paid:'<span class="pill">Paid</span>',skipped:'<span class="pill">Skipped</span>',done:'<span class="pill">Completed</span>',later:'<span class="pill">Later</span>'};
function money(){const live=S.acc.filter(a=>!a.archived);const liquid=live.filter(a=>a.type!=='card'&&!a.sav).reduce((s,a)=>s+bal(a),0);const svd=live.filter(a=>a.sav).reduce((s,a)=>s+bal(a),0);const owedCard=live.filter(a=>a.type==='card').reduce((s,a)=>s+Math.min(0,bal(a)),0);const left=S.com.reduce((s,c)=>s+camt(c)*dueOccs(c).length,0);const paid=S.tx.filter(t=>t.cid&&t.type==='exp'&&t.date>=addD(TODAY,-30)).reduce((s,t)=>s+t.amt,0);const over=S.com.filter(c=>!c.goal).reduce((s,c)=>s+c.amt*dueOccs(c).filter(d=>d<TODAY).length,0);const pp=people();let owedMe=0,iOwe=0;for(const k in pp){if(pp[k]>0)owedMe+=pp[k];else iOwe-=pp[k]}const avail=liquid+owedCard;return{liquid,owedCard,avail,left,paid,over,free:avail-left,owedMe,iOwe,net:avail+svd+owedMe-iOwe,saved:svd}}

const tagChips=(cur,act)=>{const L=allTags();return L.length?`<div class="chips" style="margin-top:8px">${L.slice(0,8).map(g=>`<button class="chip${cur===g?' on':''}" data-a="${act}" data-v="${esc(g)}">#${esc(g)}</button>`).join('')}</div>`:''};
function txView(t){const c=catOf(t.cat),a=accOf(t.acc);let title=t.note,sub,icon=c.i,sign=-1,dk=false;switch(t.type){case'exp':title=title||c.n;sub=`${c.s} · ${a.name}`;break;case'inc':title=title||c.n;sub=`${c.s}${t.person?' from '+t.person:''} · ${a.name}`;sign=1;break;case'tr':title=title||'Transfer';sub=`${a.name} → ${accOf(t.to).name}`;icon='swap';sign=0;break;case'lend':title=`Lent to ${t.person}`;sub=`${t.note?t.note+' · ':''}${a.name}`;icon='hand';break;case'borrow':title=`Borrowed from ${t.person}`;sub=`${t.note?t.note+' · ':''}${a.name}`;icon='hand';sign=1;break;case'repayIn':title=`${t.person} repaid`;sub=a.name;icon='hand';sign=1;break;case'repayOut':title=`Repaid ${t.person}`;sub=a.name;icon='hand';break;case'adj':title='Balance correction';sub=a.name;icon='adj';sign=t.amt<0?-1:1;break}if(t.prj&&prjOf(t.prj))sub+=` · ${prjOf(t.prj).name}`;const col=t.type==='exp'?c.c:t.type==='inc'?'#047857':t.type==='tr'||t.type==='adj'?'#64748b':'#0369a1';return{title,sub,icon,sign,dk,col}}
function txRow(t){const v=txView(t);const amt=t.type==='adj'?Math.abs(t.amt):t.amt;return`<button class="tx" data-a="tx" data-v="${t.id}"><span class="ico${v.dk?' dk':''}${v.col?' cico':''}" ${v.col?`style="--c:${v.col}"`:''}>${ic(v.icon)}</span><span><span class="t1">${esc(v.title)}${t.att&&t.att.length?`<span class="mut" aria-label="has attachment">${ic('clip',14)}</span>`:''}</span><span class="t2">${esc(v.sub)}</span></span><span class="am${v.sign>0?' pos':''}">${v.sign>0?'+':v.sign<0?'−':''}${fmt(amt)}</span></button>`}
function prjCard(x){const k=pkOf(x.kind),u=prjSum(x.id),pc=x.est?Math.round(u.sp/x.est*100):0,over=x.est&&u.sp>x.est;return`<button class="tx prow" data-a="prjOpen" data-v="${x.id}"><span class="ico cico" style="--c:${k[3]}">${ic(k[2])}</span><span><span class="t1">${esc(x.name)}</span><span class="t2">${x.status==='done'?`Finished · ${u.n} payment${u.n===1?'':'s'}`:u.last?`Last payment ${dshort(u.last)}`:'No payments yet'}</span>${x.est?`<span class="bar" style="height:5px;margin-top:6px;display:block"><i style="width:${Math.min(100,pc)}%;background:${k[3]}"></i></span><span class="prog"><span${over?' style="color:var(--amb);font-weight:600"':''}>${over?`${fmt(u.sp-x.est)} over the estimate`:`${pc}% of ${fmt(x.est)}`}</span></span>`:''}</span><span class="rc"><span class="ra">${fmt(u.sp)}</span></span><span class="chev" aria-hidden="true">${ic('cr',18)}</span></button>`}
