function goalRow(c,compact){const s=gSaved(c),p=Math.min(100,Math.round(s/c.amt*100)),d=nextDue(c),st=cstat(c),step=camt(c),due=d&&d<=W30()&&st!=='done';
return`<button class="tx prow" data-a="com" data-v="${c.id}"><span class="ico cico" style="--c:var(--pos)">${ic('pct')}</span><span><span class="t1">${esc(c.name)}</span><span class="t2 ${c.date<TODAY&&s<c.amt&&st!=='done'?'warn':''}">${st==='done'?`Goal reached · ${fmt(s)}`:c.date<TODAY&&s<c.amt?`Target date passed · ${fmt(c.amt-s)} to go`:due?(d<=TODAY?'This month’s saving':`Next saving ${inDays(d)}`):`${fmt(s)} of ${fmt(c.amt)} · ${p}%`}</span>${compact?'':`<span class="bar" style="height:6px;display:block"><i style="width:${p}%;background:var(--pos)"></i></span><span class="prog"><span>${fmt(s)} of ${fmt(c.amt)}</span><span>by ${dshort(c.date)} ${dyear(c.date)}</span></span>`}</span><span class="rc"><span class="ra">${due?fmt(step):p+'%'}</span>${due&&d<=TODAY?'<span class="rs pos">Save now</span>':''}</span><span class="chev" aria-hidden="true">${ic('cr',18)}</span></button>`}
function comRow(c,compact){if(c.goal)return goalRow(c,compact);const st=cstat(c),d=nextDue(c),a=accOf(c.acc),lp=lastPaid(c);const unpaid=UNPAID.includes(st);const emi=c.total?`<div class="bar" style="height:5px"><i style="width:${c.done/c.total*100}%"></i></div><div class="prog"><span>${c.done} of ${c.total} paid</span><span>${fmt((c.total-c.done)*c.amt)} left</span></div>`:'';
const due=st==='done'?'All instalments paid':d?(st==='overdue'?`Overdue · ${dshort(d)}`:`${dshort(d)} · ${inDays(d)}`):lp?`Paid ${dshort(lp)}`:'Nothing due';
const RS={overdue:'<span class="rs w">Overdue</span>',today:'<span class="rs dk">Due today</span>',done:'<span class="rs">Completed</span>',skipped:'<span class="rs">Skipped</span>',paid:'<span class="rs">Paid</span>'};const sh=unpaid&&shortOf(c);
return`<button class="tx prow" data-a="com" data-v="${c.id}"><span class="ico cico" style="--c:${c.dest?'var(--pos)':catOf(c.cat).c}">${ic(c.dest?'pct':catOf(c.cat).i)}</span><span><span class="t1">${esc(c.name)}</span><span class="t2 ${st==='overdue'?'warn':''}">${due}</span>${sh?`<span class="shortl">${esc(accOf(sh.acc).name)} short by ${fmt(sh.gap)}</span>`:''}${compact?'':emi.replace(/<div/g,'<span').replace(/<\/div>/g,'</span>').replace('class="bar"','class="bar" style="display:block;height:5px"').replace('style="height:5px"','')}</span><span class="rc"><span class="ra">${fmt(c.amt)}</span>${RS[st]||''}</span><span class="chev" aria-hidden="true">${ic('cr',18)}</span></button>`}

