const est=o=>`<div class="est">${o.i?`<span class="est-i" aria-hidden="true">${ic(o.i,22)}</span>`:''}<p class="est-t">${o.t}</p>${o.d?`<p class="est-d">${o.d}</p>`:''}${o.b?`<button class="btn est-b${o.gh?' gh':''}" data-a="${o.a}"${o.v?` data-v="${o.v}"`:''}>${o.b}</button>`:''}</div>`;
let sumOpen=false;
const actSum=()=>{const p=period(roff),pv=period(roff-1),s=stats(p),sv=stats(pv),cats=Object.entries(s.cat).sort((x,y)=>y[1]-x[1]),d=s.exp-sv.exp;
 const more=V.reports().split('<!--MORE-->')[1]||'';
 return`<section class="card asum" aria-label="Summary for ${p.label}"><div class="asum-h"><button class="icb" data-a="rp" data-v="-1" aria-label="Previous month">${ic('cl',18)}</button><b>${p.label}</b><button class="icb" data-a="rp" data-v="1" aria-label="Next month" ${roff>=0?'disabled':''}>${ic('cr',18)}</button></div>
 <div class="asum-n"><p class="mut">Spent</p><p class="big">${fmt(s.exp)}</p><p class="mut asum-c">${sv.exp?`${d>0?'▲':'▼'} ${fmt(Math.abs(d))} ${d>0?'more':'less'} than ${pv.short} · `:''}Income ${fmt(s.inc)}</p></div>
 ${cats.length?`<div class="asum-cats">${cats.slice(0,3).map(([k,v])=>`<button class="asum-r" data-a="catf" data-v="${k}"><span class="asum-l"><span>${catOf(k).n}</span><b>${fmt(v)}</b></span><span class="bar" aria-hidden="true"><i style="width:${v/cats[0][1]*100}%;background:${catOf(k).c}"></i></span></button>`).join('')}</div><button class="lk asum-m" data-a="sumMore" aria-expanded="${sumOpen}">${sumOpen?'Show less':'More: all categories, daily, accounts'} ${ic(sumOpen?'cl':'cr',14,2.2)}</button>`:`<p class="mut asum-e">Nothing spent in ${p.short} yet.</p>`}</section>${sumOpen&&cats.length?more:''}`};
