function openWelcome(){AUF='welcome';sheet(`<div class="shb" style="padding:0"><div class="wl"><div class="logo">Rs</div><h1>Save first. Spend what's left.</h1><p class="mut" style="font-size:16px;margin:0">Track money in seconds, never miss an EMI, and save for what matters.</p><ul class="pts"><li><span class="ico dk">${ic('pct',20)}</span>Know what's left to spend each day</li><li><span class="ico dk">${ic('cal',20)}</span>EMI and bill reminders, Nepali or English dates</li><li><span class="ico dk">${ic('qr',20)}</span>Share your bank QR in one tap</li></ul><div style="flex:1;min-height:24px"></div>${signOpts(true)}</div></div>`,{full:true,lock:true,cls:'welcome'})}
const SIGNWHY={pro:['Sign in to start your free trial','Your trial and everything you add are kept in your account, so they survive a new phone.'],invite:['Sign in to invite friends','Invites are linked to your account so you both get your free month.'],family:['Sign in to share with family','Sharing needs an account for each person.']};
