function doSignIn(method,name,email){const c=cloud(),flow=AUF;if(c[email]&&!(S.auth&&S.auth.status==='guest'&&S.tx.length>40&&flow==='later')){S=c[email];S.auth={status:'signed',method,email,name:S.auth&&S.auth.name||name};save();while(sheets.length)closeSheet();applyTheme();tab='home';render();toast(`Welcome back · your data is restored`);return}
  S.auth={status:'signed',method,email,name};if(!S.set.name)S.set.name=name;save();while(sheets.length)closeSheet();render(1);toast(flow==='later'?'Signed in · your data is now backed up':`Signed in as ${email}`);if(!S.set.calAsked)setTimeout(openCalAsk,400)}
