function saveCom(){const amt=parseFloat(NC.amt);if(!NC.name.trim())return ferr('#nc_name','Enter a name, like Flat rent');if(!(amt>0))return ferr('#nc_amt','Enter an amount more than Rs 0');const months=(+NC.total||0)*(NC.unit==='y'?12:1);if(NC.type==='EMI'&&!(months>0))return ferr('#nc_total','Enter how long you’ll pay, like 45 months or 5 years');if(NC.type==='EMI'&&+NC.done>months)return ferr('#nc_done',`Payments already made can’t be more than ${months}`);if(NC.type==='EMI')NC.cat='emi';if(!NC.cat)return ferr('[data-a="pk"][data-v="nc_cat"]','Choose a category');
  const once=NC.rep==='once'&&NC.type!=='EMI';if(once&&!NC.date)return ferr('#nc_date','Choose the date it’s due');if(once&&NC.date<TODAY)return ferr('#nc_date','Choose a date from today onwards');
  if(EDC){const c=EDC,old=JSON.parse(JSON.stringify(c));Object.assign(c,{name:NC.name.trim(),type:NC.type,amt,cat:NC.cat,acc:NC.acc,remind:NC.remind});if(once){c.once=true;c.date=NC.date;c.due=+NC.date.slice(8);c.cal='ad'}else{delete c.once;delete c.date;c.due=NC.due;c.cal=c.cal||(S.set.cal==='bs'?'bs':'ad')}if(NC.type==='EMI'){c.total=months;c.done=Math.min(c.total,+NC.done||0)}else{delete c.total;delete c.done}save();while(sheets.length)closeSheet();render(1);toast(`${c.name} updated`,()=>{for(const k in c)delete c[k];Object.assign(c,old)});return}
  const c={id:nid(),name:NC.name.trim(),type:NC.type,amt,cat:NC.cat,acc:NC.acc,due:once?+NC.date.slice(8):NC.due,cal:once?'ad':(S.set.cal==='bs'?'bs':'ad'),since:TODAY,remind:NC.remind,paid:[],skip:[]};if(once){c.once=true;c.date=NC.date}if(NC.type==='EMI'){c.total=months;c.done=Math.min(c.total,+NC.done||0)}
  S.com.push(c);save();closeSheet();tab='plan';render();const n=nextDue(c);toast(`${c.name} added · first due ${dshort(n||c.date)} · reminder ${c.remind} days before`,()=>{S.com=S.com.filter(x=>x.id!==c.id)})}

