function openAcc(id){const a=S.acc.find(x=>x.id===id),p=period(0);const L=sorted().filter(t=>t.acc===id||t.to===id);const inn=L.filter(t=>inP(t,p)).reduce((s,t)=>s+Math.max(0,delta(t,id)),0),out=L.filter(t=>inP(t,p)).reduce((s,t)=>s+Math.min(0,delta(t,id)),0);const b=bal(a);
  sheet(`${head(esc(a.name))}<div class="shb"><div class="card"><p class="mut">${a.type==='card'?'Amount owed':'Current balance'}</p><p class="big">${a.type==='card'?fmt(b):sfmt(b)}</p><div class="kv" style="margin-top:10px"><span class="mut">In · ${p.label}</span><b>+${fmt(inn)}</b></div><div class="kv" style="margin-top:4px"><span class="mut">Out · ${p.label}</span><b>−${fmt(out)}</b></div><div class="kv" style="margin-top:4px"><span class="mut">Opening balance</span><b>${sfmt(a.open)}</b></div>${(()=>{const L=a.type==='card'?[]:S.com.filter(c=>c.acc===a.id).flatMap(c=>dueOccs(c).map(d=>[c,d]));const tot=L.reduce((s,x)=>s+camt(x[0]),0);return L.length?`<div style="margin-top:12px;padding-top:12px;border-top:1px solid var(--line)"><div class="kv"><b>Kept aside · next 30 days</b><b>${fmt(tot)}</b></div>${L.map(([c,d])=>`<div class="kv" style="margin-top:4px"><span class="mut">${esc(c.name)} · ${dshort(d)}</span><span>${fmt(camt(c))}</span></div>`).join('')}<div class="kv" style="margin-top:8px"><b>Available</b><b>${sfmt(b-tot)}</b></div></div>`:''})()}</div>
  ${a.type==='bank'||a.type==='wallet'?`<label class="chk card" style="margin-top:12px"><input type="checkbox" data-a="savtog" data-v="${a.id}" ${a.sav?'checked':''}><span>Savings account</span><small>${a.sav?'Not counted in Left to spend.':'Turn on to keep this money out of Left to spend.'}</small></label>`+detCard(a):''}
  <span class="l">Balance looks wrong? Enter the real one</span><div style="display:flex;gap:8px"><input class="in" id="corr" inputmode="decimal" placeholder="${Math.round(b)}"><button class="pay" style="height:48px" data-a="corr" data-v="${a.id}">Fix</button></div><p class="mut" style="font-size:13px;margin-top:6px">The difference is saved as a correction, not as spending.</p>
  <div class="hd"><h2>Transactions</h2><span class="mut">${L.length}</span></div><div class="card" style="padding:4px 16px">${L.slice(0,25).map(txRow).join('')||'<p class="empty">No transactions on this account yet.</p>'}</div>
  <button class="btn wr" data-a="arch" data-v="${a.id}">Archive account</button><p class="mut" style="font-size:13px;margin-top:8px">Archived accounts are hidden; their history stays.</p></div>`)}
