let D=null;
const mask=n=>{n=String(n||'');return n.length>4?'•••• '+n.slice(-4):n};
function luhn(s){let t=0,f=false;for(let i=s.length-1;i>=0;i--){let d=+s[i];if(f){d*=2;if(d>9)d-=9}t+=d;f=!f}return t%10===0}
function detRisk(o){const all=[o.holder,o.num,o.branch].join(' ');const dg=String(o.num||'').replace(/[\s-]/g,'');const card=/^[2-6]\d{14,15}$/.test(dg)&&luhn(dg);return card||/\b(pin|m-?pin|cvv|cvc|password|passcode|otp)\b/i.test(all)}
const detFields=o=>{const F=o.fromQR||{},w=o.type==='wallet',st=o.qrSt,touch=matchMedia('(pointer:coarse)').matches;
  const fl=(k,lbl,ph,im)=>`<label class="fld"><span class="fl">${lbl}${F[k]?'<span class="fq">From QR</span>':''}</span><input class="in" id="d_${k}" value="${esc(o[k])}" placeholder="${ph}" ${im?`inputmode="${im}"`:''} autocomplete="off"></label>`;
  const msg={ok:'Check the name below is yours before saving.',none:'Saved as an image. You can still show and share it.',fail:'You can still show and share this image.'}[st]||'Shown when you share it to get paid';
  const card=st==='reading'?`<div class="qrc"><div class="qrrow"><span class="ico dk spin">${ic('qr',22)}</span><div><b>Reading your QR…</b><small>This takes a second</small></div></div></div>`
   :o.qr?`<div class="qrc${st==='fail'?' qwarn':''}"><div class="qrrow"><img class="qrimg" src="${o.qr}" alt="Your payment QR"><div style="min-width:0"><b>${st==='fail'?'Couldn’t read this QR':st==='ok'||st==='none'?(o.src?esc(o.src)+' QR read':'QR read'):'Your QR'}</b><small>${msg}</small></div></div><div class="qra"><button class="btn gh" data-a="dqr">Replace</button><button class="btn gh" data-a="dqrx">Remove</button></div></div>`
   :`<div class="qrc qempty"><div class="qrrow"><span class="ico dk">${ic('qr',22)}</span><div><b>Add your payment QR</b><small>Take a photo or choose a screenshot of your eSewa, Khalti or bank QR, so you can show or share it to get paid.</small></div></div><div class="qra">${touch?`<button class="btn" data-a="dqr" data-v="cam">${ic('cam',18)} Take photo</button><button class="btn gh" data-a="dqr">Choose image</button>`:`<button class="btn" data-a="dqr">Choose QR image</button>`}</div></div>`;
  const rd=o.qr&&(o.src||o.holder)?`<p class="mut" style="font-size:13px;margin-top:8px">Read from QR: ${esc([o.src,o.holder].filter(Boolean).join(' · '))}</p>`:'';
  return `${o.id?'':'<h3 class="gh3" style="margin-bottom:10px">Payment QR <span class="mut" style="font-weight:500">· optional</span></h3>'}${card}${rd}<p class="mut" style="font-size:12px;margin-top:10px">Only the QR image is saved. No account numbers, card numbers or PINs.</p>`}
function bindDet(b){const m={d_holder:'holder',d_num:'num',d_branch:'branch'};for(const k in m){const el=b.querySelector('#'+k);if(el)el.oninput=e=>{D[m[k]]=e.target.value;if(D.fromQR&&D.fromQR[m[k]]){delete D.fromQR[m[k]];const q=el.parentNode.querySelector('.fq');if(q)q.remove()}const w=b.querySelector('#d_warn');if(w)w.style.display=detRisk(D)?'':'none'}}}
