const detOf=o=>{if(!o.qr)return null;const d={qr:o.qr};if(o.qrPath&&d.qr.indexOf('data:')!==0)d.qrPath=o.qrPath;if(o.qrText)d.qrText=o.qrText;if(o.src)d.src=o.src;if(o.holder)d.holder=String(o.holder).trim();return d};
function detCard(a){const d=a.det;if(!d||!d.qr)return`<button class="drop" data-a="det" data-v="${a.id}" style="margin-top:12px"><span class="ico dk">${ic('qr',22)}</span><span><b>Add payment QR</b><small>Optional. Show or share it when someone pays you</small></span></button>`;return`<div class="card"><div class="kv"><b>Payment QR</b><button class="lk" data-a="det" data-v="${a.id}">Change</button></div><button data-a="qrfull" data-v="${a.id}" style="display:block;margin:10px auto 4px;border:0;background:#fff;padding:8px;border-radius:14px" aria-label="Show QR full screen"><img src="${d.qr}" alt="Payment QR for ${esc(a.name)}" style="width:150px;height:150px;object-fit:contain;display:block"></button><div class="row2"><button class="btn gh" data-a="qrfull" data-v="${a.id}">${ic('eye',18)} Show</button><button class="btn" data-a="share" data-v="${a.id}">${ic('share',18)} Share</button></div></div>`}
