const detText=a=>{const d=a.det||{};return[`Pay me by QR · ${a.name}`,d.holder&&`Name: ${d.holder}`].filter(Boolean).join('\n')};
function qrFile(url,name){return new Promise(res=>{const im=new Image();im.onload=()=>{const w=im.naturalWidth||600,h=im.naturalHeight||600,c=document.createElement('canvas');c.width=w;c.height=h;const x=c.getContext('2d');x.fillStyle='#fff';x.fillRect(0,0,w,h);x.drawImage(im,0,0,w,h);c.toBlob(b=>res(b?new File([b],name.replace(/\W+/g,'-')+'-qr.png',{type:'image/png'}):null),'image/png')};im.onerror=()=>res(null);im.src=url})}
/* ---------- Payment QR: read a photo, pull out name and number ---------- */
function ensureQR(){return window.jsQR?Promise.resolve():new Promise(r=>{const x=document.createElement('script');x.src='js/vendor/jsQR.min.js';x.onload=x.onerror=()=>r();document.head.appendChild(x)})}
function pickImg(cam,cb){const i=document.createElement('input');i.type='file';i.accept='image/*';if(cam)i.setAttribute('capture','environment');i.onchange=()=>{const f=i.files&&i.files[0];if(!f)return;if(f.size>15*1024*1024)return toast('That image is over 15 MB');const r=new FileReader();r.onload=()=>cb(r.result);r.readAsDataURL(f)};i.click()}
// Finds a QR code in the image. Returns {text, crop} (crop = a clean square image of just the code) or null.
function readQR(url){return new Promise(res=>{const im=new Image();im.onload=async()=>{const W=im.naturalWidth||1,H=im.naturalHeight||1;
  const draw=mx=>{const k=Math.min(1,mx/Math.max(W,H)),w=Math.max(1,Math.round(W*k)),h=Math.max(1,Math.round(H*k)),c=document.createElement('canvas');c.width=w;c.height=h;const x=c.getContext('2d',{willReadFrequently:true});x.fillStyle='#fff';x.fillRect(0,0,w,h);x.drawImage(im,0,0,w,h);return c};
  const crop=(c,pts)=>{const xs=pts.map(p=>p.x),ys=pts.map(p=>p.y),x0=Math.min(...xs),x1=Math.max(...xs),y0=Math.min(...ys),y1=Math.max(...ys),side=Math.max(x1-x0,y1-y0)*1.12,cx=(x0+x1)/2,cy=(y0+y1)/2,o=document.createElement('canvas'),n=Math.min(640,Math.max(240,Math.round(side)));o.width=o.height=n;const g=o.getContext('2d');g.fillStyle='#fff';g.fillRect(0,0,n,n);g.imageSmoothingEnabled=false;g.drawImage(c,cx-side/2,cy-side/2,side,side,0,0,n,n);return o.toDataURL('image/png')};
  if('BarcodeDetector' in window){try{const c=draw(1600),bd=new BarcodeDetector({formats:['qr_code']}),f=(await bd.detect(c))[0];if(f&&f.rawValue)return res({text:f.rawValue,crop:crop(c,f.cornerPoints)})}catch(e){}}
  await ensureQR();if(!window.jsQR)return res(null);
  for(const mx of[1200,800,500,1800]){const c=draw(mx),d=c.getContext('2d').getImageData(0,0,c.width,c.height),r=jsQR(d.data,c.width,c.height,{inversionAttempts:'attemptBoth'});if(r&&r.data){const L=r.location;return res({text:r.data,crop:crop(c,[L.topLeftCorner,L.topRightCorner,L.bottomLeftCorner,L.bottomRightCorner])})}}
  res(null)};im.onerror=()=>res(null);im.src=url})}
// EMVCo tag-length-value (NepalQR, Fonepay, NepalPay and most bank QRs)
function tlv(t){const o={};let i=0;while(i<t.length){const k=t.substr(i,2),n=t.substr(i+2,2);if(!/^\d\d$/.test(k)||!/^\d\d$/.test(n))return null;o[k]=t.substr(i+4,+n);i+=4+ +n}return i===t.length?o:null}
const WALLETS=[[/esewa/i,'eSewa'],[/khalti/i,'Khalti'],[/ime ?pay|imepay/i,'IME Pay'],[/fonepay/i,'Fonepay'],[/connectips|nchl|nepalpay/i,'NepalPay'],[/prabhu ?pay/i,'Prabhu Pay'],[/mypay/i,'MyPay']];
const walletOf=t=>{for(const[r,n]of WALLETS)if(r.test(t||''))return n;return''};
const MOB=/(?:\+?977[-\s]?)?\b(9[678]\d{8})\b/;
// Returns {holder, num, branch, src}; empty strings when not found.
function parseQR(raw){const t=String(raw||'').trim(),out={holder:'',num:'',branch:'',src:''};
  const pickNum=vals=>{vals=vals.filter(v=>v&&/^[A-Za-z0-9@._+-]{5,40}$/.test(v)&&!/\.(com|np|org)$/i.test(v));return(vals.find(v=>MOB.test(v))||vals.find(v=>/^\d{8,}$/.test(v))||vals[0]||'').replace(/^\+?977[-\s]?/,'')};
  if(/^000201/.test(t)){const o=tlv(t);if(o){out.holder=(o['59']||'').trim();const city=(o['60']||'').trim(),vals=[];let guid='';
    for(let k=26;k<=51;k++){const v=o[String(k)];if(!v)continue;const sub=tlv(v);if(k===29)out.src='NepalPay';if(sub){guid+=' '+(sub['00']||'');for(const j in sub)if(j!=='00')vals.push(sub[j].trim())}else vals.push(v.trim())}
    const add=o['62']&&tlv(o['62']);if(add&&add['02'])vals.push(add['02']);
    out.src=walletOf(guid)||out.src||'NepalQR';out.num=pickNum(vals);out.branch=[out.src,city&&!/^n\/?a$/i.test(city)?city.replace(/\b\w/g,c=>c.toUpperCase()).replace(/\B\w+/g,w=>w.toLowerCase()):''].filter(Boolean).join(' · ');return out}}
  if(/^[\[{]/.test(t)){try{const j=JSON.parse(t),flat={};const walk=(x,p)=>{for(const k in x){if(x[k]&&typeof x[k]==='object')walk(x[k],k);else flat[k]=String(x[k])}};walk(Array.isArray(j)?j[0]||{}:j,'');const keys=Object.keys(flat);
    const kh=keys.find(k=>/(^|_)(full_?)?name$|holder|account_?name|^name/i.test(k)),kn=keys.find(k=>/(esewa|khalti|wallet|ime)_?id|mobile|phone|account_?(no|num|number)?$|^id$|_id$/i.test(k)&&!/name/i.test(k));
    out.holder=kh?flat[kh].trim():'';out.num=kn?flat[kn].trim().replace(/^\+?977[-\s]?/,''):pickNum(Object.values(flat));out.src=walletOf(keys.join(' ')+' '+(flat.type||flat.provider||flat.wallet||''));out.branch=out.src;return out}catch(e){}}
  if(/^https?:\/\//i.test(t)){try{const u=new URL(t),h=u.hostname.replace(/^www\./,''),seg=u.pathname.split('/').filter(Boolean);
    if(/venmo\.com$/.test(h)){out.src='Venmo';out.num='@'+(seg[0]==='u'?seg[1]:seg[0]||'')}
    else if(/zellepay\.com$/.test(h)&&u.searchParams.get('data')){out.src='Zelle';try{const z=JSON.parse(atob(u.searchParams.get('data')));out.holder=z.name||'';out.num=z.token||''}catch(e){}}
    else if(/paypal\.me$/.test(h)){out.src='PayPal';out.num='paypal.me/'+(seg[0]||'')}
    else if(/cash\.app$/.test(h)){out.src='Cash App';out.num=seg[0]||''}
    else{const q=u.searchParams;out.holder=q.get('name')||q.get('pn')||'';out.num=q.get('id')||q.get('pa')||q.get('account')||q.get('mobile')||'';out.src=walletOf(h)||''}
    out.branch=out.src;return out}catch(e){}}
  const nz=/\b(\d{2})-(\d{4})-(\d{7})-(\d{2,3})\b/.exec(t);if(nz){out.num=nz[0];out.src='NZ bank account';out.branch='';return out}
  const m=MOB.exec(t);out.num=m?m[1]:(/\b\d{8,20}\b/.exec(t)||[''])[0];out.src=walletOf(t);out.branch=out.src;return out}
const qrTop=()=>setTimeout(()=>{const q=top().querySelector('.qrc');if(q)q.scrollIntoView({block:'start',behavior:'smooth'})},60);
const nameCase=v=>v&&v===v.toUpperCase()&&/[A-Z]/.test(v)?v.toLowerCase().replace(/(^|[\s.'-])\p{L}/gu,c=>c.toUpperCase()):v;
async function gotQR(url){D.qrSt='reading';reDet();qrTop();const r=await readQR(url);const isNA=D===NA;
  for(const k in(D.fromQR||{}))D[k]='';if(isNA&&NA.qrName){NA.name='';NA.qrName=false}
  if(!r){shrink(url,u=>{D.qr=u;D.qrText=null;D.src='';D.fromQR={};D.qrSt='fail';reDet();qrTop()});return}
  const p=parseQR(r.text);p.holder=nameCase(p.holder);D.qr=r.crop;D.qrText=r.text;D.src=p.src;D.fromQR={};let n=0;
  for(const k of['holder','num','branch'])if(p[k]){D[k]=p[k];D.fromQR[k]=1;n++}
  if(isNA&&p.src&&/eSewa|Khalti|IME Pay|Prabhu Pay|MyPay|Venmo|PayPal|Cash App|Zelle/.test(p.src)){if(NA.type!=='wallet')NA.type='wallet';if(!NA.name.trim()){NA.name=p.src;NA.qrName=true}}
  D.qrSt=n?'ok':'none';reDet();qrTop()}
function shrink(url,cb){const im=new Image();im.onload=()=>{const s=Math.min(1,700/Math.max(im.naturalWidth||700,im.naturalHeight||700)),w=Math.round((im.naturalWidth||700)*s),h=Math.round((im.naturalHeight||700)*s),c=document.createElement('canvas');c.width=w;c.height=h;const x=c.getContext('2d');x.fillStyle='#fff';x.fillRect(0,0,w,h);x.drawImage(im,0,0,w,h);cb(c.toDataURL('image/png'))};im.onerror=()=>cb(url);im.src=url}
function copyText(t,msg){const fb=()=>sheet(`${head('Copy and send')}<div class="shb"><p class="mut" style="font-size:14px">Copying isn't allowed in this preview. Select the text below and copy it.</p><textarea class="in" rows="6" readonly style="margin-top:10px">${esc(t)}</textarea></div>`);try{navigator.clipboard.writeText(t).then(()=>toast(msg)).catch(fb)}catch(e){fb()}}
async function shareDet(id){const a=accOf(id),d=a.det||{},text=detText(a);try{if(navigator.share){const o={title:a.name,text};if(d.qr){const f=await qrFile(d.qr,a.name);if(f&&navigator.canShare&&navigator.canShare({files:[f]}))o.files=[f]}await navigator.share(o);toast('Shared');return}}catch(e){if(e&&e.name==='AbortError')return}copyText(text,'Details copied. Paste them in WhatsApp or Viber.')}
function openQR(id){const a=accOf(id),d=a.det||{};sheet(`${head(esc(a.name))}<div class="shb" style="text-align:center">${d.qr?`<div style="background:#fff;border-radius:22px;padding:14px;margin:6px auto 0;max-width:330px"><img src="${d.qr}" alt="QR code for ${esc(a.name)}" style="width:100%;display:block"></div><p class="mut" style="margin-top:10px">Show this to the person paying you, or share it.</p>`:'<p class="mut" style="margin-top:10px">No QR saved for this account yet.</p>'}${d.holder?`<p style="font-weight:650;font-size:17px;margin:12px 0 0">${esc(d.holder)}</p>`:''}${d.num?`<p class="mut" style="margin:2px 0 0">${a.type==='wallet'?'ID':'Account no.'} ${esc(d.num)}</p>`:''}${d.branch?`<p class="mut" style="margin:2px 0 0">${esc(d.branch)}</p>`:''}<button class="btn" data-a="share" data-v="${a.id}">${ic('share',18)} Share QR and details</button><button class="btn gh" data-a="copyDet" data-v="${a.id}">${ic('copy',18)} Copy text only</button>${d.qr?'':`<button class="btn gh" data-a="det" data-v="${a.id}">Add QR image</button>`}</div>`,{full:true})}
function openRecv(){const L=S.acc.filter(a=>!a.archived&&(a.type==='bank'||a.type==='wallet'));sheet(`${head('Receive money')}<div class="shb"><p class="mut" style="font-size:14px">Pick where you want to be paid. Show the QR or share it on WhatsApp or Viber.</p>${L.sort((x,y)=>(y.det&&y.det.qr?1:0)-(x.det&&x.det.qr?1:0)).map(a=>`<button class="acc" data-a="${a.det&&a.det.qr?'qrfull':'det'}" data-v="${a.id}"><span class="ico">${ic(a.det&&a.det.qr?'qr':ATYPE[a.type][1])}</span><span><span class="t1">${esc(a.name)}</span><span class="t2">${a.det&&a.det.qr?'Show or share QR':'Add payment QR'}</span></span><span class="am" style="font-size:14px">${a.det&&a.det.qr?ic('cr',18):ic('plus',18)}</span></button>`).join('')}</div>`)}
function saveAcc(){if(!NA.name.trim())return ferr('#na_name','Enter a name for this account');if(S.acc.some(a=>!a.archived&&a.name.trim().toLowerCase()===NA.name.trim().toLowerCase()))return ferr('#na_name',`You already have an account called “${NA.name.trim()}”. Use a different name`);const v=parseFloat(NA.open)||0;const a={id:nid(),name:NA.name.trim(),type:NA.type,open:NA.type==='card'?-Math.abs(v):v};if(NA.type==='bank'||NA.type==='wallet'){const d=detOf(NA);if(d)a.det=d;if(NA.sav)a.sav=true}S.acc.push(a);save();closeSheet();tab='accounts';render();toast(`${a.name} added`,()=>{S.acc=S.acc.filter(x=>x.id!==a.id)})}

let NI=null;
function openInc(id){const r=id&&S.inc.find(x=>x.id===id);NI=r?{id:r.id,name:r.name,amt:String(r.amt),acc:r.acc,day:r.day,cal:r.cal,src:r.src}:{id:null,name:'Salary',amt:'',acc:S.acc.find(a=>a.type==='bank'&&!a.archived)?.id||S.set.def,day:5,cal:S.set.cal==='bs'?'bs':'ad',src:'salary'};sheet(`${head(r?'Expected income':'Add expected income')}<div class="shb" id="nib">${niBody()}</div><div class="foot"><button class="btn" data-a="saveInc">${r?'Save changes':'Add income'}</button>${r?`<button class="btn wr" data-a="delInc" data-v="${r.id}">${ic('trash',18)} Remove</button>`:''}</div>`,{full:true});bindNI()}
function niBody(){const n=occ({due:NI.day,cal:NI.cal},TODAY,addD(TODAY,400))[0];return`<p class="mut" style="font-size:14px">Set it once. On the day, the app asks “Got it?” and adds it with one tap. Nothing is counted until you confirm.</p><span class="l">Name</span><input class="in" id="ni_name" value="${esc(NI.name)}" placeholder="e.g. Salary, Rent from tenant"><span class="l">Source</span><div class="chips">${SRCS.map(c=>`<button class="chip${NI.src===c.id?' on':''}" data-a="nisrc" data-v="${c.id}">${c.s}</button>`).join('')}</div><div class="row2"><div><span class="l">Usual amount (Rs)</span><input class="in" id="ni_amt" inputmode="decimal" value="${esc(NI.amt)}" placeholder="0"></div><div><span class="l">Day it arrives</span>${pkBtn('ni_day')}</div></div><span class="l">Calendar</span><div class="seg"><button class="${NI.cal==='bs'?'on':''}" data-a="nical" data-v="bs">Nepali (BS)</button><button class="${NI.cal==='ad'?'on':''}" data-a="nical" data-v="ad">English (AD)</button></div>${n?`<p class="mut" style="font-size:13px;margin-top:6px">Next: <b>${dboth(n)}</b></p>`:''}<span class="l">Received in</span><div class="chips scroll">${S.acc.filter(a=>!a.archived&&a.type!=='card').map(a=>`<button class="chip${NI.acc===a.id?' on':''}" data-a="niacc" data-v="${a.id}">${ic(ATYPE[a.type][1],18)} ${esc(a.name)}</button>`).join('')}</div>`}
function bindNI(){const b=top().querySelector('#nib');b.querySelector('#ni_name').oninput=e=>NI.name=e.target.value;b.querySelector('#ni_amt').oninput=e=>NI.amt=e.target.value;0}
function reNI(){const b=top().querySelector('#nib'),st=b.scrollTop;b.innerHTML=niBody();b.scrollTop=st;bindNI()}
function saveInc(){const amt=parseFloat(NI.amt);if(!NI.name.trim())return ferr('#ni_name','Enter a name, like Salary');if(!(amt>0))return ferr('#ni_amt','Enter the usual amount, more than Rs 0');let r=NI.id&&S.inc.find(x=>x.id===NI.id);if(r)Object.assign(r,{name:NI.name.trim(),amt,acc:NI.acc,day:NI.day,cal:NI.cal,src:NI.src});else{r={id:nid(),name:NI.name.trim(),amt,acc:NI.acc,day:NI.day,cal:NI.cal,src:NI.src,got:[],skip:[],snooze:null,since:TODAY};S.inc.push(r)}save();closeSheet();render(1);const n=incNext(r);toast(`${r.name} saved${n?' · next '+dshort(n):''}`)}
function runAuto(){if(!S.set.autoInc)return;let k=0;for(const r of S.inc){const d=incPending(r);if(!d)continue;S.tx.push({id:nid(),type:'inc',amt:r.amt,acc:r.acc,cat:r.src,date:d,note:r.name,att:[],rid:r.id,rd:d});r.got.push(d);k++}if(k){save();setTimeout(()=>toast(k===1?'Expected income added automatically':`${k} incomes added automatically`),600)}}
function calDefault(){let tz='';try{tz=Intl.DateTimeFormat().resolvedOptions().timeZone||''}catch(e){}return tz==='Asia/Kathmandu'||tz==='Asia/Katmandu'?'bs':'ad'}
// The calendar is no longer its own screen: a default from the phone's time zone, changeable in setup step 1 and in You
function openCalAsk(){S.set.cal=S.set.cal&&S.set.calAsked?S.set.cal:calDefault();S.set.calAsked=true;roff=0;save();render();afterCal()}
function openCalAskOld(){sheet(`<div class="shb" style="padding-top:18px"><h3 style="margin:0 0 6px;font-size:21px">Which calendar do you use?</h3><p class="mut" style="font-size:14px">Dates, months in Reports and new EMI due days will follow it. Change it any time in Settings.</p><button class="btn" data-a="calPick" data-v="bs" style="flex-direction:column;align-items:flex-start;padding:14px 18px"><span>Nepali (Bikram Sambat)</span><small style="font-weight:500;opacity:.8">Today is ${bsShort(TODAY)} ${bsOf(TODAY)?bsOf(TODAY).y:''}</small></button><button class="btn gh" data-a="calPick" data-v="ad" style="flex-direction:column;align-items:flex-start;padding:14px 18px"><span>English (AD)</span><small style="font-weight:500;opacity:.8">Today is ${adShort(TODAY)} ${T.getFullYear()}</small></button></div>`)}
let ST=null;
function openSettle(n){const v=people()[n]||0;ST={n,amt:String(Math.abs(Math.round(v))),acc:S.set.def,dir:v>0?'in':'out'};const w=sheet(`${head('Record repayment')}<div class="shb"><div class="card"><p class="mut">${v>0?`${esc(n)} owes you`:`You owe ${esc(n)}`}</p><p class="big">${fmt(v)}</p></div><span class="l">${v>0?'Amount received':'Amount paid back'} (Rs)</span><input class="in" id="st_amt" inputmode="decimal" value="${ST.amt}"><span class="l">${v>0?'Received in':'Paid from'}</span><div class="chips" id="stc">${stChips()}</div><p class="mut" style="font-size:13px;margin-top:10px">Partial amounts are fine; the rest stays outstanding.</p></div><div class="foot"><button class="btn" data-a="saveSt">Save repayment</button></div>`);w.querySelector('#st_amt').oninput=e=>ST.amt=e.target.value}
