function openBudget(){const p=period(0),s=stats(p);sheet(`${head('Budget')}<div class="shb" id="bb"><span class="l">Overall monthly limit (Rs)</span><input class="in" data-b="all" inputmode="decimal" value="${S.bud.all}"><p class="mut" style="font-size:13px;margin-top:6px">Alerts at 80% and 100%. Paid EMIs count toward it.</p><span class="l">Per category (leave empty for no limit)</span>${CATS.map(c=>`<div style="display:grid;grid-template-columns:42px minmax(0,1fr) 120px;gap:10px;align-items:center;margin-top:8px">${cic(c.id)}<span><span class="t1" style="font-size:14px">${c.n}</span><span class="t2">spent ${fmt(s.cat[c.id]||0)}</span></span><input class="in" data-b="${c.id}" inputmode="decimal" value="${S.bud.cat[c.id]||''}" placeholder="No limit" aria-label="${c.n} limit"></div>`).join('')}</div><div class="foot"><button class="btn" data-a="saveBud">Save budget</button></div>`,{full:true})}
function saveBud(){const old=JSON.parse(JSON.stringify(S.bud));top().querySelectorAll('[data-b]').forEach(el=>{const v=parseFloat(el.value);if(el.dataset.b==='all'){if(v>0)S.bud.all=v}else if(v>0)S.bud.cat[el.dataset.b]=v;else delete S.bud.cat[el.dataset.b]});save();closeSheet();render(1);toast('Budget saved',()=>{S.bud=old})}

function openNotifs(){const n=Object.assign({due:true,save:true,inc:true,eve:!!S.set.remind},S.set.notif||{});const row=(k,t,d)=>`<label class="rowb" style="cursor:pointer"><span style="flex:1"><b style="font-weight:600">${t}</b><small>${d}</small></span><input type="checkbox" class="sw-in" data-a="ntog" data-v="${k}" ${n[k]?'checked':''} aria-label="${t}"></label>`;
  sheet(`${head('Notifications')}<div class="shb"><div class="card lst">${row('due','Bills and EMIs','Before and on the due day, as set on each plan')}${row('save','Saving reminders','Once a month for each goal or saving')}${row('inc','Salary check','On the day your income is expected')}${row('eve','Evening reminder','8 pm, only on days with nothing recorded')}</div><span class="l">Quiet hours</span><div class="card" style="margin-top:0"><div class="kv"><span>No notifications</span><b>10 pm – 7 am</b></div><p class="mut" style="font-size:13px;margin-top:6px">Anything due then arrives at 7 am.</p></div><p class="mut" style="font-size:13px;margin-top:10px">Reminders work offline. This preview doesn't send real notifications.</p></div>`)}
function openHelp(){const q=[['How is Left to spend worked out?','Money in your accounts (not savings), minus card owed, minus what’s kept aside for bills, EMIs and savings due in the next 30 days. Tap the card on Home to see each amount.'],['Why isn’t my salary counted yet?','Income counts only after you add it, so Left to spend never includes money that hasn’t arrived. Tap Add salary on Home when it comes.'],['Does the app move my money?','No. When you pay a bill or save, do it in your bank or wallet app, then tap Mark paid or Mark saved here to record it.'],['What if my balance doesn’t match my bank?','Open the account in Accounts and enter the real balance. The difference is saved as a correction, not spending.'],['How do I use Nepali dates?','In You, choose Nepali (BS). Each bill keeps the calendar it was set up in.']];
  sheet(`${head('Help and feedback')}<div class="shb">${q.map(x=>`<details class="card faq"><summary><b>${x[0]}</b></summary><p class="mut" style="font-size:14px;margin:8px 0 0">${x[1]}</p></details>`).join('')}<span class="l">Send feedback</span><textarea class="in" id="fb" rows="4" style="height:auto;padding-top:12px" placeholder="What’s working, what isn’t?"></textarea><button class="btn" data-a="fbSend">Send</button></div>`)}
function openPrivacy(){const L=[['What we store','Your accounts, transactions, plans, slips and QR images, and your name and email if you sign in. Nothing else.'],['What we never collect','Bank logins, card numbers, CVV, PINs or passwords. We don’t read your SMS or connect to your bank.'],['Where it’s kept','Without an account: only on this phone. Signed in: also in your private account (Supabase), where only you can read your data.'],['Who sees it','Only you. Slips and QR images are private files. We don’t sell data or show ads.'],['Usage analytics','Only if you allow it, and never with amounts, notes, names or account numbers.'],['Your controls','Export a file any time. Sign out removes your data from this phone. Delete account erases everything.']];
  sheet(`${head('Privacy')}<div class="shb"><p class="mut" style="font-size:14px;margin:0 0 4px">In short: your money data is yours, kept private, and you can take it or delete it any time.</p>${L.map(x=>`<div class="card"><b>${x[0]}</b><p class="mut" style="font-size:14px;margin:6px 0 0">${x[1]}</p></div>`).join('')}<p class="mut" style="font-size:13px;margin-top:12px">The full privacy policy and terms will be linked here before launch.</p></div>`)}
function openExport(){const rows=[['Date','Type','Amount','Account','To','Category','Person','Note','Attachments']].concat(sorted().map(t=>[t.date,t.type,t.amt,accOf(t.acc).name,t.to?accOf(t.to).name:'',t.cat?catOf(t.cat).n:'',t.person||'',t.note||'',(t.att||[]).length]));const csv=rows.map(r=>r.map(v=>/[",\n]/.test(String(v))?`"${String(v).replace(/"/g,'""')}"`:v).join(',')).join('\n');
  EXP=csv;sheet(`${head('Export')}<div class="shb"><p class="mut" style="font-size:14px">A spreadsheet file of all ${S.tx.length} transactions: date, type, amount, account, category, person and note. Opens in Excel or Google Sheets.</p><button class="btn" data-a="expFile">${ic('share',18)} Save or share file</button><button class="lk" data-a="copy" style="margin-top:8px">Copy as text instead</button><textarea class="in" id="csv" rows="6" readonly aria-label="CSV text" style="margin-top:12px;font-size:12px">${esc(csv)}</textarea></div>`)}
let EXP='';
async function expFile(){const name=`expense-tracker-${TODAY}.csv`,f=new File([EXP],name,{type:'text/csv'});try{if(navigator.canShare&&navigator.canShare({files:[f]})){await navigator.share({files:[f],title:name});return}}catch(e){if(e&&e.name==='AbortError')return}const u=URL.createObjectURL(f),l=document.createElement('a');l.href=u;l.download=name;document.body.appendChild(l);l.click();l.remove();setTimeout(()=>URL.revokeObjectURL(u),2000);toast(`Saved ${name}`)}

